app.use(express.json({ limit: '10kb' })); // Parse JSON + size cap
app.use(morgan('combined'));              // Log every request

// ----- Routes ------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users',
  query('name').optional().isString().isLength({ max: 50 }),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Validation fails → 400
      return res.status(400).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    // Example filter
    const result = req.query.name
      ? users.filter(u => u.name.includes(req.query.name))
      : users;

    res.json(result);
  });

app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// ----- Error Handler --------------------------------------
app.use((err, req, res, next) => {
  console.error(err);                                       // capture stack once
  const httpStatus = err.status || 500;
  res.status(httpStatus).json({
    error: { message: err.message || 'Internal Server Error' }
  });
});

// ----- Server ------------------------------------------------
const PORT = process.env.PORT ?? 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = app;
```

