// app.js
// --------------------------------------------------------------
// 1️⃣  Dependencies
// --------------------------------------------------------------
const express    = require('express');
const helmet     = require('helmet');
const cors       = require('cors');
const rateLimit  = require('express-rate-limit');
const dotenv     = require('dotenv');
const { body, query } = require('express-validator');
const app        = express();

// 2️⃣  Load env vars
dotenv.config();
const PORT = process.env.PORT || 3000;

// 3️⃣  Middleware
app.use(helmet());                              // Security headers
app.use(cors({ origin: process.env.CORS_ORIGIN || false })); // Restrict origins
app.use(express.json());                        // Parse JSON bodies
app.use(express.urlencoded({ extended: true }));// Parse URL‑encoded bodies

// 4️⃣  Basic rate limiter (10 req/min per IP)
const apiLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 10,
  handler: (_, res) =>
    res.status(429).json({ error: 'Too many requests – try again later.' }),
});
app.use(apiLimiter);

// 5️⃣  Routes with validation
app.get('/health', (_, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example: sort user list – sanitises query
app.get(
  '/users',
  [
    query('sort')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('sort must be "asc" or "desc"'),
  ],
  (req, res, next) => {
    const errors = require('express-validator').validationResult(req);
    if (!errors.isEmpty()) return next({ status: 400, errors: errors.array() });

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];
    const sorted = req.query.sort === 'desc' ? users.reverse() : users;
    res.json(sorted);
  }
);

// 6️⃣  404 catch‑all (must come after all real routes)
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// 7️⃣  Global error handler
app.use((err, _, res, __) => {
  /* eslint-disable no-console */
  console.error(err);
  /* eslint-enable no-console */

  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  const payload = { error: message };
  if (status === 400 && err.errors) payload.details = err.errors;
  res.status(status).json(payload);
});

// 8️⃣  Process‑wide error catcher
process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  process.exit(1);
});
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled rejection:', reason);
  process.exit(1);
});

// 9️⃣  Start server
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

