## 4. Suggested Refactored `app.js`

Below is a **drop‑in** refactor that incorporates the best practices above while keeping the existing functionality intact.

```js
/**
 *  app.js - Secure Express App
 *  --------------------------------
 *  * Global error handling
 *  * Input validation pattern
 *  * Security middleware (Helmet, CORS, RateLimit)
 *  * Logging for 404s
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
require('dotenv').config(); // for NODE_ENV, etc.

const app = express();

/* ────────────────── SECURITY MIDDLEWARE ────────────────── */
app.use(helmet());                                 // Sets security headers
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' }));  // Restrict or allow origins
app.use(rateLimit({                                 // Basic rate limiting
  windowMs: 15 * 60 * 1000,                        // 15 minutes
  max: 200,                                        // 200 requests per IP
  message: { error: 'Too many requests, try again later.' }
}));
app.use(express.json({ limit: '1mb' }));           // Limit body size
app.set('trust proxy', true);                      // HSTS when behind proxy

/* ────────────────── ROUTES ────────────────── */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example of validated route – can be used for /users ?search param
 * User may pass ?page=1&pageSize=20 for pagination (future extension)
 */
app.get('/users',
  // Validation middleware
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('pageSize').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 Bad Request – sanitised validation errors
      return res.status(400).json({ errors: errors.array() });
    }

    // As we have no DB yet, just return hard‑coded users
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // In production, map to a DTO to avoid sending internal IDs
    res.json(users);
  }
);

/* ────────────────── 404 Handler ────────────────── */
app.use((req, res) => {
  console.warn(`Unhandled route: ${req.method} ${req.originalUrl}`);
  res.status(404).json({ error: 'Not Found' });
});

/* ────────────────── GLOBAL ERROR HANDLER ────────────────── */
app.use((err, req, res, next) => {
  console.error(err); // Log full stack

  const status = err.status || 500;
  const response = {
    error: status === 500 ? 'Internal Server Error' : err.message,
  };

  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

/* ────────────────── START SERVER ────────────────── */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = app;
```

