## 7. Global Error Handling Middleware

```js
// 1. Catch async errors (use express‑promise‑errors or wrap with a helper)
// 2. Centralised error handler

// Example async wrapper
const asyncHandler = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Replace routes with asyncHandler if they become async
app.get('/health', asyncHandler(async (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
}));

// Global error handler
app.use((err, req, res, next) => {
  // Log error details (stack trace) but never expose them to the client
  logger.error({ err, url: req.originalUrl, ip: req.ip }, 'Unhandled exception');

  // Do NOT send stack trace to end‑users
  if (process.env.NODE_ENV === 'production') {
