const app = express();

/* ------------------------------------------------------------------
   Security Middlewares
------------------------------------------------------------------- */
app.use(helmet());               // Secure HTTP headers
app.use(xssClean());             // Sanitises user inputs
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 200,                 // max requests per window
    standardHeaders: true,
    legacyHeaders: false,
  })
);

/* ------------------------------------------------------------------
   Body parser (future‑proof)
