/**
 * Simple application for agent to work on
 * Security‑aware rewrite – focus on error handling & input validation
 */
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

/* ---------------------------------------------------------
 * ⚙️  Global middleware – order matters!
 * --------------------------------------------------------- */
const PORT = process.env.PORT || 3000;

// Security headers
app.use(helmet());          // Sets HTTP headers reliably
app.use(cors());            // Add custom whitelist if needed

// Request body parser
app.use(express.json());    // Handles JSON; returns 400 for bad JSON

// Rate limit – 60 req/min per IP
const limiter = rateLimit({
  windowMs: 60 * 1000,
  max: 60,
  standardHeaders: true,   // Return rate‑limit info in headers
  legacyHeaders: false,    // Disable legacy `X-RateLimit-*` headers
});
app.use(limiter);

/* ---------------------------------------------------------
 * 👤  Routes
 * --------------------------------------------------------- */
app.get('/health', (_, res) => {
  return res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

/**
 * GET /users?id=<int>
 * - `id` is optional, must be a positive integer if present.
 * - Validation is handled via express‑validator.
 */
app.get(
  '/users',
  // Validation middleware
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('id must be a positive integer')
    .toInt(),

  // Actual handler
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 – Bad Request
      return res.status(400).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const { id } = req.query;
    const result = id ? users.filter((u) => u.id === id) : users;
    return res.json(result);
  }
);

/* ---------------------------------------------------------
 * 🛠  Global error handler
 * --------------------------------------------------------- */
app.use((err, _req, res, next) => {
  // Log the full stack, but keep the response generic
  console.error('Unhandled error:', err);

  // Avoid leaking stack traces to the client
  res.status(500).json({ error: 'Internal Server Error' });
});

/* ---------------------------------------------------------
 * 🖥️  Start server
 * --------------------------------------------------------- */
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

/* Export for tests / external use */
module.exports = app;

/* ---------------------------------------------------------
 * 🛑  Unhandled promise rejection handler
 * --------------------------------------------------------- */
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Optional: exit process or reconnect
});

```

