/**
 * Minimal, production‑ready Express skeleton
 *
 * Security best‑practice tour‑guide:
 *   - Helmet    : Harden HTTP headers
 *   - Rate limiter : Mitigate brute‑force / DoS
 *   - CORS      : Control cross‑origin
 *   - HPP       : HTTP parameter pollution protection
 *   - Input validation : Joi
 *   - Central error handling
 *   - Environment driven configuration
 *
 * Install the dependencies before running:
 *   npm i helmet express-rate-limit cors hpp @hapi/joi dotenv morgan
 *
 * (Add the optional packages you need – the code only uses the ones above)
 */

import express from 'express';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import cors from 'cors';
import hpp from 'hpp';
import dotenv from 'dotenv';
import morgan from 'morgan';
import Joi from '@hapi/joi';
import http from 'http';
import createError from 'http-errors';

// Load environment variables (e.g. PORT, ALLOWED_ORIGINS)
dotenv.config();

const APP_PORT = process.env.PORT || 3000;
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || '*').split(',');

const app = express();

/* ------------------------------------------------------------------ */
/* 1. Basic Security Middleware                                      */
/* ------------------------------------------------------------------ */
app.use(helmet());                    // Secure headers
app.use(hpp());                       // Block duplicate query params

// CORS – allow only from ALLOWED_ORIGINS
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow same‑origin requests from the browser
      if (!origin) return callback(null, true);
      if (ALLOWED_ORIGINS.includes('*') || ALLOWED_ORIGINS.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    optionsSuccessStatus: 204,
  })
);

/* ------------------------------------------------------------------ */
/* 2. Request body / query middleware                               */
/* ------------------------------------------------------------------ */
app.use(express.json({ limit: '10kb' }));   // Body parser
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

/* ------------------------------------------------------------------ */
/* 3. Rate limiting – 100 requests / 15 minutes per IP              */
/* ------------------------------------------------------------------ */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    status: 'error',
    message: 'Too many requests, please try again later.',
  },
});

app.use(limiter);

/* ------------------------------------------------------------------ */
/* 4. Public routes                                                   */
/* ------------------------------------------------------------------ */

/**
 * Health‑check
 *   GET /health
 *   Response: { status: 'ok', timestamp: <ISO timestamp> }
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *   Query params can be validated if required (page/limit, etc.)
 */
app.get('/users', (req, res) => {
  // In a real app you would fetch from a DB; here we hard‑code for demo.
  const users = [
    {
      id: 1,
      name: 'Alice',
      email: 'alice@example.com',
    },
    {
      id: 2,
      name: 'Bob',
      email: 'bob@example.com',
    },
  ];

  res.json(users);
});

/* ------------------------------------------------------------------ */
/* 5. Not‑found handler – 404                           */
/* ------------------------------------------------------------------ */
app.use((_req, _res, next) => {
  next(createError(404, 'Resource not found'));
});

/* ------------------------------------------------------------------ */
/* 6. Centralised error handling middleware                        */
/* ------------------------------------------------------------------ */
app.use((err, _req, res, _next) => {
  // Log the error (could replace with a proper logger)
  console.error(err);

  const status = err.status || 500;

  // In production we don't expose stack traces; we only show a generic msg
  const response = {
    status: 'error',
    message: err.message || 'Internal Server Error',
  };

  // Optionally add stack trace in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

/* ------------------------------------------------------------------ */
/* 7. Server launch, handles both normal and '/dev' environments    */
/* ------------------------------------------------------------------ */
const server = http.createServer(app);

server.listen(APP_PORT, () => {
  console.log(`🚀 Server is listening on port ${APP_PORT}`);
});

/* ------------------------------------------------------------------ */
/* 8. Graceful shutdown handling                                     */
/* ------------------------------------------------------------------ */
const gracefulShutdown = () => {
  console.log('\n🛑 Shutting down gracefully...');
  server.close(() => {
    console.log('✅ Server closed, exiting process.');
    process.exit(0);
  });
};

process
  .on('SIGTERM', gracefulShutdown)
  .on('SIGINT', gracefulShutdown);

/* ------------------------------------------------------------------ */
/* 9. Unhandled promise rejections & exceptions                    */
/* ------------------------------------------------------------------ */
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  // You can decide to exit or log.
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

export default app;
```

